syntax:
try {
  <codigo que pode falhar>
} catch {
  <tratamento>
} finally {
  <sempre executa>
}

example:
try {
  Get-Content -Path "arquivo-inexistente.txt" -ErrorAction Stop
} catch {
  Write-Warning "Falha ao ler arquivo: $($_.Exception.Message)"
}

